// resposta paginada do node HTTP Request chega como 1 item por PÁGINA
// (cada item.json = array daquela página, quando a paginação nativa
// está ativa), ou já achatada em N items — cobre os dois casos e
// concatena tudo num array único, igual buscarTudo() do backfill.
const brutos = $input.all().map((i) => i.json);
let linhas = [];
for (const b of brutos) {
  if (Array.isArray(b)) linhas = linhas.concat(b);
  else linhas.push(b);
}

function pgVal(v) {
  if (v === null || v === undefined) return 'NULL';
  if (typeof v === 'boolean') return v ? 'TRUE' : 'FALSE';
  if (typeof v === 'number') return Number.isFinite(v) ? String(v) : 'NULL';
  if (typeof v === 'object') return `'${JSON.stringify(v).replace(/'/g, "''")}'::jsonb`;
  return `'${String(v).replace(/'/g, "''")}'`;
}

// Mesmo mapeamento de sincronizarProdutos() em backfill_periodo.js:
// ProdutoIntegracaoDto não tem "marca" -- nomeLaboratorio é a
// aproximação (fabricante); categoria = nomeCategoria (tipo de uso),
// grupo = nomeGrupo (categoria de produto de verdade) -- campos
// separados de propósito (achado 01/08/2026).
const COLUNAS = [
  'codigo', 'codigo_barras', 'nome', 'categoria', 'grupo', 'marca',
  'preco_venda', 'custo_medio', 'estoque_atual', 'tipo_lista', 'principio_ativo', 'chave_equivalencia',
];

// <chaveEquivalencia> CÓPIA de coletor/chaveEquivalencia.js (Code node não importa
// arquivo) — não editar aqui; editar lá e recopiar (testar_chave_equivalencia.js
// confere se as duas estão iguais).
const NUM = '\\d+(?:[.,]\\d+)*';
const SEM_LETRA_ANTES = '(?<![A-Z])'; // "30CP": não há \b entre dígito e letra
const forma = (alternativas) => new RegExp(`${SEM_LETRA_ANTES}(${alternativas})(?![A-Z])`);

// Sinônimos -> código canônico. A ORDEM importa: a primeira que casar
// vence ("500MG ENV 10CP" é comprimido em envelope, não sachê — por isso
// SAC/ENV/PO fica por último).
const FORMAS = [
  [forma('CP|CPR|COMP|DRG|DG|TABS'), 'CP'],
  [forma('CAP|CAPS|CPS|CAPSULA'), 'CAP'],
  [forma('GTS|GOTAS'), 'GTS'],
  [forma('XPE|XAROPE'), 'XPE'],
  [forma('SUSP|SUS'), 'SUSP'],
  [forma('SOL|LIQ'), 'SOL'],
  [forma('SPR|SPRAY|AER|JAT'), 'SPR'],
  [forma('POM'), 'POM'],
  [forma('CR|CREME'), 'CR'],
  [forma('GEL'), 'GEL'],
  [forma('AMP|INJ|FA'), 'INJ'],
  [forma('SUP|SUPOS'), 'SUP'],
  [forma('PAST'), 'PAST'],
  [forma('COL|COLIRIO'), 'COL'],
  [forma('SAC|SACHE|PO|ENV'), 'SAC'],
];

const MODS = [
  [forma('L\\.?P|XR|AP|RETARD|L\\.?R|L\\.?C|ER|SR|OD|UD'), 'LIB'],
  [forma('MAST'), 'MAST'],
  [forma('EFERV|EFEV|EFER|EFV'), 'EFERV'],
  [forma('DISP|DISPERS'), 'DISP'],
  [forma('SUBL'), 'SUBL'],
  [forma('ODT|ORODISP'), 'ODT'],
  [forma('PED|INF|INFANTIL'), 'PED'],
  [forma('AD|ADULTO'), 'AD'],
  [forma('NAS'), 'NAS'],
  [forma('OFT'), 'OFT'],
  [forma('VAG'), 'VAG'],
  [forma('DERM'), 'DERM'],
];

const RE_CONCENTRACAO = new RegExp(
  `(${NUM}(?:\\s*(?:MG|MCG|G|UI|%))?(?:\\s*\\+\\s*${NUM})*)\\s*(MG|MCG|G|UI|%)(?:\\s*\\/\\s*(${NUM})?\\s*(ML|G|GTS|DOSE|5))?`
);
const RE_QTD_UNIDADES = /(?<![\d.,])(\d+)\s*(CP|CPR|COMP|CAP|CAPS|CPS|SAC|ENV|AMP|SUP|PAST|DRG|UN|FLAC|TABS)(?![A-Z])/;
const RE_VOLUME = new RegExp(`(${NUM})\\s*(ML|G)(?![A-Z])(?!\\s*\\/)`, 'g');

// "3.300" = três mil e trezentos (ponto de milhar: exatamente 3 dígitos
// depois); "0,15" e "2.5" = decimal.
function numero(texto) {
  const t = /^\d{1,3}(\.\d{3})+$/.test(texto) ? texto.replace(/\./g, '') : texto.replace(',', '.');
  return String(Number(t));
}

function normalizarPrincipioAtivo(valor) {
  const texto = valor == null ? '' : String(valor).trim().toUpperCase().replace(/\s+/g, ' ');
  return texto || null;
}

function lerApresentacao(nomeProduto) {
  const nome = String(nomeProduto || '').toUpperCase().replace(/\s+/g, ' ').trim();

  const c = nome.match(RE_CONCENTRACAO);
  let concentracao = null;
  if (c) {
    const partes = c[1]
      .replace(/\s/g, '')
      .split('+')
      .map((p) => numero(p.replace(/(MG|MCG|G|UI|%)$/, '')));
    concentracao = partes.join('+') + c[2] + (c[4] ? `/${c[3] ? numero(c[3]) : ''}${c[4]}` : '');
  }

  const formaEncontrada = FORMAS.find(([re]) => re.test(nome));
  const modificadores = MODS.filter(([re]) => re.test(nome))
    .map(([, m]) => m)
    .sort()
    .join('.');

  let quantidade = null;
  const u = nome.match(RE_QTD_UNIDADES);
  if (u) {
    quantidade = u[1];
  } else {
    const volumes = [...nome.matchAll(RE_VOLUME)];
    const ultimo = volumes[volumes.length - 1];
    // não confundir com a própria concentração ("1G" de "DIPIRONA 1G")
    if (ultimo && !(c && ultimo.index === c.index)) quantidade = numero(ultimo[1]) + ultimo[2];
  }

  return { concentracao, forma: formaEncontrada ? formaEncontrada[1] : null, modificadores, quantidade };
}

function chaveEquivalencia(nomeProduto, principioAtivo) {
  const pa = normalizarPrincipioAtivo(principioAtivo);
  if (!pa) return null;
  const a = lerApresentacao(nomeProduto);
  if (!a.concentracao || !a.forma || !a.quantidade) return null;
  return [pa, a.concentracao, a.forma, a.modificadores, a.quantidade].join('|');
}
// </chaveEquivalencia>
const ATUALIZAR = COLUNAS.slice(1).map((c) => `${c} = EXCLUDED.${c}`).join(', ');
const TAMANHO_LOTE = 500;

const saida = [];
for (let inicio = 0; inicio < linhas.length; inicio += TAMANHO_LOTE) {
  const lote = linhas.slice(inicio, inicio + TAMANHO_LOTE);
  const grupos = lote.map((p) => {
    const valores = [
      p.codigo,
      p.codigoBarras != null ? String(p.codigoBarras) : null,
      p.nome,
      p.nomeCategoria ?? null,
      p.nomeGrupo ?? null,
      p.nomeLaboratorio ?? null,
      p.valorVenda ?? 0,
      p.valorCustoMedio ?? p.valorCusto ?? 0,
      p.quantidadeEstoque ?? 0,
      p.tipoLista ?? null,
      normalizarPrincipioAtivo(p.nomePrincipioAtivo),
      chaveEquivalencia(p.nome, p.nomePrincipioAtivo),
    ];
    return `(${valores.map(pgVal).join(', ')})`;
  });
  const sql = `INSERT INTO produto_catalogo (${COLUNAS.join(', ')})
VALUES ${grupos.join(',\n')}
ON CONFLICT (codigo) DO UPDATE SET ${ATUALIZAR};`;
  saida.push({ json: { sql, tipo: 'lote', quantidade: lote.length } });
}

if (linhas.length === 0) {
  saida.push({ json: { sql: 'SELECT 1', tipo: 'vazio', quantidade: 0 } });
}

// Última linha: atualiza sync_control (upsert -- 'produto' pode nunca
// ter tido linha aqui, já que era fora do escopo do incremental).
saida.push({
  json: {
    sql: `INSERT INTO sync_control (entity_name, last_synced_at) VALUES ('produto', now())
ON CONFLICT (entity_name) DO UPDATE SET last_synced_at = now();`,
    tipo: 'sync_control',
    quantidade: linhas.length,
  },
});

return saida;
